def solve(g):
    H,W=len(g),len(g[0])
    o=[r[:] for r in g]
    shapes=[]
    for r in range(H-2):
        for c in range(W-2):
            if g[r+1][c+1]==2 and all(g[r+i][c+j]==3 for i in range(3) for j in range(3) if (i,j)!=(1,1)):
                shapes.append((r+1,c+1))
    vlines=[c for c in range(W) if all(g[r][c]==2 for r in range(H))]
    hlines=[r for r in range(H) if all(g[r][c]==2 for c in range(W))]
    for (sr,sc) in shapes:
        if sc in vlines:
            kind='row'; crossings=[c for c in vlines if c!=sc]
        else:
            kind='col'; crossings=[r for r in hlines if r!=sr]
        # full axis line of 1s except shape cells
        for t in range(W if kind=='row' else H):
            r,c=(sr,t) if kind=='row' else (t,sc)
            if g[r][c]!=3:
                o[r][c]=1
        # 3x3 block at each crossing; center keeps original value
        for p in crossings:
            cr,cc=(sr,p) if kind=='row' else (p,sc)
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    r,c=cr+dr,cc+dc
                    if 0<=r<H and 0<=c<W:
                        o[r][c]=g[r][c] if (dr,dc)==(0,0) else 1
        # restore shape (blocks/line must never eat the shape)
        for i in range(-1,2):
            for j in range(-1,2):
                o[sr+i][sc+j]=g[sr+i][sc+j]
    return o

